WITH input(id, name, email, online, last_login_at, updated_at, new_version, expected_version) AS ( VALUES
(#{player.id}, #{player.name}, #{player.email}, #{player.online}, #{player.lastLoginAt}, #{player.updatedAt}, CAST(#{player.version} AS INTEGER), CAST(#{player.expectedVersion} AS INTEGER))
), upserted AS ( INSERT INTO users (id, name, email, online, last_login_at, updated_at, version) SELECT id, name, email, online, last_login_at, updated_at, new_version FROM input ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, email = EXCLUDED.email, online = EXCLUDED.online, last_login_at = EXCLUDED.last_login_at, updated_at = EXCLUDED.updated_at, version = EXCLUDED.version WHERE users.version = ( SELECT expected_version FROM input WHERE input.id = users.id ) RETURNING id, name, email, online, last_login_at, updated_at, version ) SELECT id, name, email, online, last_login_at, updated_at, version FROM upserted
